package com.priperi;
import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.test.core.app.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.io.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Synthetic local accounts only. Core crypto/protocol is exercised without pretending emulator biometrics authenticate. */
@RunWith(AndroidJUnit4.class) public class RecoveryFlowTest {
 private Context context;private Vault active,peer;private final List<Vault> extra=new ArrayList<>();private final List<File> files=new ArrayList<>();private String owner,peerId,device,fingerprint;private final String password="Recovery-Test-Password-2026!";
 private <T>T local(Repository.Job<T> job)throws Exception{CompletableFuture<T> done=new CompletableFuture<>();Repository.local(context,v->{try{return job.run(v);}catch(Throwable e){done.completeExceptionally(e);return null;}},done::complete,e->done.completeExceptionally(new AssertionError(e)));return done.get(60,TimeUnit.SECONDS);}
 private File file()throws Exception{File f=File.createTempFile("priperi-recovery-test-",".enc",context.getCacheDir());files.add(f);return f;}
 private Vault receiver(boolean same)throws Exception{Vault n=new Vault(context,"qa_receiver_"+UUID.randomUUID());extra.add(n);if(same)n.identity().put("deviceId",device);return n;}
 @Before public void setup()throws Exception{context=ApplicationProvider.getApplicationContext();assertTrue(BuildConfig.ALLOW_TEST_DEVICES);assertTrue(BuildConfig.BACKEND_URL.startsWith("http://10.0.2.2:"));context.getSharedPreferences("notification_access",0).edit().putBoolean("asked",true).commit();Repository.reset();local(v->{assertNull(v.account());String suffix=UUID.randomUUID().toString().substring(0,8);owner=Session.continueAccount(v,"qa_recover_"+suffix,password).getString("uid");device=v.identity().getString("deviceId");fingerprint=v.identity().getString("fingerprint");active=v;peer=new Vault(context,"qa_recovery_peer_"+suffix);peerId=Session.continueAccount(peer,"qa_recpeer_"+suffix,password).getString("uid");TestIdentityTrust.pin(peer,Repository.call(peer,"lookupUser",new JSONObject().put("uid",owner)));Session.restore(v);TestIdentityTrust.pin(v,Repository.call(v,"lookupUser",new JSONObject().put("uid",peerId)));JSONObject env=v.crypto().encrypt(owner,v.identity(),v.contact(peerId),"Saved private message");v.store(new JSONObject().put("peer",peerId).put("body","Saved private message").put("envelope",env).put("outgoing",true).put("state","delivered"));Repository.send(v,peerId,"Queued private message");v.mute(peerId,-1);return true;});}
 @After public void cleanup()throws Exception{if(context==null)return;local(v->{Session.restore(peer);if(peer.account()!=null)Session.resetAccount(peer);Session.restore(active);if(active.account()!=null)Session.resetAccount(active);Repository.eraseLocal(v);return true;});if(peer!=null)peer.destroy();for(Vault v:extra)v.destroy();for(File f:files)f.delete();Repository.reset();}
 @Test public void samePhoneRecoveryAndAnotherReinstallKeepAccountKeysChatsAndRevokeOldSessions()throws Exception{File backup=file();local(v->{try(AccountRecovery.Offer offer=AccountRecovery.prepare(v,backup,true,password.toCharArray())){AccountRecovery.register(v,offer);String oldToken=v.session().getString("access_token"),oldProof=v.identity().getString("deviceSecret");Vault next=receiver(true);Session.forget();AccountRecovery.inspect(next,backup,offer.words);assertNull(next.account());AccountRecovery.restore(next,password.toCharArray());active=next;assertEquals(owner,Session.uid());assertEquals(fingerprint,next.identity().getString("fingerprint"));assertEquals(2,next.messages(peerId).size());assertTrue(next.muted(peerId));assertNull(next.transferIn());assertEquals(2,next.account().getJSONArray("delegations").length());assertThrows(Session.BackendException.class,()->Session.request(Session.endpoint(),new JSONObject().put("operation","getAccount").put("deviceSecret",oldProof),oldToken,true));
  String sample="Restored phone signs";Crypto.verifySignature(next.accountWithIdentity(),sample.getBytes(Crypto.UTF8),next.crypto().sign(sample.getBytes(Crypto.UTF8)));
  Vault again=receiver(false);Session.forget();AccountRecovery.inspect(again,backup,offer.words);AccountRecovery.restore(again,password.toCharArray());active=again;assertEquals(owner,Session.uid());assertEquals(fingerprint,again.identity().getString("fingerprint"));assertEquals(2,again.messages(peerId).size());assertTrue(Repository.call(again,"getRecoveryStatus",new JSONObject()).getBoolean("enabled"));assertNull(again.transferIn());assertNotEquals(next.identity().getString("installation"),again.identity().getString("installation"));}return true;});}
 @Test public void wrongWordsCorruptionAndWrongCurrentPasswordLeaveOldAccountAndHistoryUntouched()throws Exception{File backup=file(),corrupt=file();local(v->{try(AccountRecovery.Offer offer=AccountRecovery.prepare(v,backup,true,password.toCharArray())){AccountRecovery.register(v,offer);Vault next=receiver(false);byte[] wrong=offer.words.clone();wrong[0]^=1;assertThrows(Exception.class,()->AccountRecovery.inspect(next,backup,wrong));assertNull(next.transferIn());try(InputStream in=new FileInputStream(backup);OutputStream out=new FileOutputStream(corrupt)){RecoveryBundle.copy(in,out,RecoveryBundle.MAX_BYTES);}try(RandomAccessFile f=new RandomAccessFile(corrupt,"rw")){long end=f.length()-1;f.seek(end);int before=f.read();f.seek(end);f.write(before^1);}assertThrows(Exception.class,()->AccountRecovery.inspect(next,corrupt,offer.words));assertNull(next.transferIn());File deeplyNested=file(),opaque=file();try(FileOutputStream out=new FileOutputStream(opaque)){out.write(1);}String nested="{\"x\":"+"[".repeat(100)+"0"+"]".repeat(100)+"}";RecoveryBundle.write(deeplyNested,RecoveryCipher.seal(nested.getBytes(Crypto.UTF8),offer.words),opaque);assertThrows(Exception.class,()->AccountRecovery.inspect(next,deeplyNested,offer.words));assertNull(next.transferIn());AccountRecovery.inspect(next,backup,offer.words);Session.forget();assertThrows(Exception.class,()->AccountRecovery.restore(next,"Wrong-Recovery-Password-2026!".toCharArray()));assertNull(next.account());assertTrue(next.transferIn().getBoolean("recovery"));Session.restore(v);assertEquals(owner,Repository.call(v,"getAccount",new JSONObject()).getString("uid"));assertEquals(2,v.messages(peerId).size());Session.forget();AccountRecovery.restore(next,password.toCharArray());active=next;assertEquals(2,next.messages(peerId).size());}return true;});}
 @Test public void identityOnlyBackupKeepsContactsAndMuteButDoesNotExportMessagesAndCanBeRevoked()throws Exception{File backup=file();local(v->{try(AccountRecovery.Offer offer=AccountRecovery.prepare(v,backup,false,password.toCharArray())){AccountRecovery.register(v,offer);Vault next=receiver(false);Session.forget();AccountRecovery.inspect(next,backup,offer.words);assertFalse(next.transferIn().getBoolean("includesChats"));AccountRecovery.restore(next,password.toCharArray());active=next;assertEquals(0,next.messages(null).size());assertNotNull(next.contact(peerId));assertTrue(next.muted(peerId));Repository.call(next,"revokeRecovery",new JSONObject());assertFalse(Repository.call(next,"getRecoveryStatus",new JSONObject()).getBoolean("enabled"));Vault rejected=receiver(false);Session.forget();AccountRecovery.inspect(rejected,backup,offer.words);assertThrows(Exception.class,()->AccountRecovery.restore(rejected,password.toCharArray()));assertNull(rejected.account());Session.restore(next);}return true;});}
 @Test public void creationRequiresStrongBiometricsAndScreenSurvivesPauseRotation()throws Exception{try(ActivityScenario<RecoveryActivity> scenario=ActivityScenario.launch(RecoveryActivity.class)){await(scenario,"Create recovery backup");scenario.onActivity(a->find(a.getWindow().getDecorView(),"Create recovery backup").performClick());await(scenario,"Set up a supported fingerprint");scenario.moveToState(androidx.lifecycle.Lifecycle.State.CREATED);scenario.moveToState(androidx.lifecycle.Lifecycle.State.RESUMED);await(scenario,"Create recovery backup");scenario.recreate();await(scenario,"Create recovery backup");local(v->{assertFalse(Repository.call(v,"getRecoveryStatus",new JSONObject()).getBoolean("enabled"));return true;});}}
 private static View find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View n=find(g.getChildAt(i),text);if(n!=null)return n;}}return null;}
 private static void await(ActivityScenario<RecoveryActivity> s,String text){for(int i=0;i<150;i++){boolean[] ok={false};s.onActivity(a->{View n=find(a.getWindow().getDecorView(),text);ok[0]=n!=null&&n.isShown();});if(ok[0])return;SystemClock.sleep(50);}fail("Missing recovery UI: "+text);}
}
